ee:message.ee:set-payload:
%dw 2.0 output application/json
var source = payload var thirdApp = source.thirdApp var deliveryChannel = source.deliveryChannel
--- { "partnerCode": thirdApp.partnerCode, "sendMail": deliveryChannel.sendMail }

%dw 2.0
output application/json

// Variables de control para facilitar el acceso
var response = payload.ActivateRefreshResponse
var metadata = response.ResponseMetadata

---
{
  // El código lo manejamos como String según tu destino
  "code": "200",  
  "message": "Notification processed successfully",
  "data": {
    "notificationType": "ActivateRefresh",
    "responseMetadata": {
      "timeStamp": metadata.timeStamp,
      "requestID": metadata.requestID
    }
  }
}
